static void check(bool b,const char* s){if(!b)throw std::runtime_error(std::string(s)+": "+alui::message);std::cout<<"PASS "<<s<<'\n';}
static std::string label(const char* s){std::string v=s;auto p=v.find("##");return p==v.npos?v:v.substr(0,p);}
