 auto p=ReyondBroomPluginInit(&h);check(p&&alui::ready,"full host initializes");auto click=[&](const char* s){clicked=s;p->draw();check(clicked.empty(),s);check(depth==0,"balanced disabled stack");};auto wait=[&]{for(int i=0;p->busy()&&i<15000;i++){p->tick();std::this_thread::sleep_for(std::chrono::milliseconds(1));}check(!p->busy(),"background finishes");};p->draw();alui::builders[0].seed=1;alui::changed();click("Rebuild All");wait();check(segments>100&&!alui::preview.map.empty(),"preview generated");check(alui::builders[0].levelData.layers[1].valid,"auto advance builds decor");auto original=alui::preview.map;click("Apply to map");check(imported.size()>10000&&imported.find("info_player_start")!=imported.npos&&imported.find("_tb_group")!=imported.npos,"single import contains groups and player");
