 auto beforePreset=alui::builders[0];choices["Preset"]=3;p->draw();check(alui::builders[0].levelData.size==al::Int3{5,5,6}&&alui::builders[0].moduleWeightMultipliers.at("stair")==1.5f,"Tower preset only multiplies stair weights by 1.5");alui::builders[0]=beforePreset;alui::changed();
 for(auto name:{"Blocks Repo","Block Asset","Big Block","Builders Window","Level Builder"})click(name);
