 alui::repos[0].blocks.back().active=false;alui::changed();click("Rebuild All");wait();check(!alui::preview.map.empty(),"fresh preview after capture");document++;p->tick();check(alui::preview.map.empty(),"document change invalidates preview");
 click("Rebuild All");wait();documentRevision++;p->tick();check(alui::preview.map.empty(),"same-map edit revision invalidates preview");
