 auto quotedRepo=al::defaultRepo();quotedRepo.name="Repo \"quoted\"";quotedRepo.blocks[0].name="Block \"quoted\"";quotedRepo.blocks[0].uid="quoted-block";auto workbench=al::buildWorkbench(quotedRepo,{},2);check(!al::parseMap(workbench.map).brushes.empty(),"workbench escapes quoted labels and UIDs");
 auto saved=files;auto corrupt="plugin-autolevel-repo-"+alui::repos[0].uid+".txt";files[corrupt]="broken";p=ReyondBroomPluginInit(&h);p->draw();int beforeWrites=writes;alui::changed();alui::editedAt-=std::chrono::seconds(3);p->tick();p->shutdown();check(writes==beforeWrites&&files[corrupt]=="broken","corrupt file is not overwritten by autosave/shutdown");files=saved;
